<?php require"config/auth.php";require"config/db.php";$msg="";if(isset($_GET["return"])){$id=(int)$_GET["return"];$l=$conn->query("SELECT book_id FROM loans WHERE id=$id AND status='Issued'")->fetch_assoc();if($l){$conn->query("UPDATE loans SET status='Returned',return_date=CURDATE() WHERE id=$id");$conn->query("UPDATE books SET available=available+1 WHERE id=".$l["book_id"]);}$msg="Book returned successfully.";}if($_SERVER["REQUEST_METHOD"]==="POST"){$b=(int)$_POST["book_id"];$m=(int)$_POST["member_id"];$d=$_POST["due_date"];$av=$conn->query("SELECT available FROM books WHERE id=$b")->fetch_assoc();if($av&&$av["available"]>0){$s=$conn->prepare("INSERT INTO loans(book_id,member_id,issue_date,due_date) VALUES(?,?,CURDATE(),?)");$s->bind_param("iis",$b,$m,$d);$s->execute();$conn->query("UPDATE books SET available=available-1 WHERE id=$b");$msg="Book issued successfully.";}else{$msg="Selected book is not available.";}}$books=$conn->query("SELECT id,title,available FROM books WHERE available>0 ORDER BY title");$members=$conn->query("SELECT id,name FROM members ORDER BY name");$loans=$conn->query("SELECT l.*,b.title,m.name FROM loans l JOIN books b ON l.book_id=b.id JOIN members m ON l.member_id=m.id ORDER BY l.id DESC");?><!doctype html><html><head><title>Loans</title><link rel="stylesheet" href="assets/style.css"></head><body><?php include"nav.php";?><main class="container"><h1>Issue / Return Books</h1><?php if($msg):?><div class="alert"><?=htmlspecialchars($msg)?></div><?php endif;?><div class="card"><h2>Issue Book</h2><form method="post" class="grid"><div><label>Book</label><select name="book_id" required><?php while($b=$books->fetch_assoc()):?><option value="<?=$b["id"]?>"><?=htmlspecialchars($b["title"])?> (<?=$b["available"]?> available)</option><?php endwhile;?></select></div><div><label>Member</label><select name="member_id" required><?php while($m=$members->fetch_assoc()):?><option value="<?=$m["id"]?>"><?=htmlspecialchars($m["name"])?></option><?php endwhile;?></select></div><div><label>Due Date</label><input type="date" name="due_date" required value="<?=date("Y-m-d",strtotime("+14 days"))?>"></div><div style="align-self:end"><button class="btn">Issue Book</button></div></form></div><div class="card"><table><tr><th>Book</th><th>Member</th><th>Issue Date</th><th>Due Date</th><th>Return Date</th><th>Status</th><th>Action</th></tr><?php while($r=$loans->fetch_assoc()):?><tr><td><?=htmlspecialchars($r["title"])?></td><td><?=htmlspecialchars($r["name"])?></td><td><?=$r["issue_date"]?></td><td><?=$r["due_date"]?></td><td><?=$r["return_date"]??"-"?></td><td><span class="badge <?=$r["status"]=="Returned"?"returned":""?>"><?=$r["status"]?></span></td><td><?php if($r["status"]=="Issued"):?><a class="btn success" href="?return=<?=$r["id"]?>">Return</a><?php endif;?></td></tr><?php endwhile;?></table></div></main></body></html>